ALTER TABLE public.billing_plans ADD COLUMN self_service_enabled boolean NOT NULL DEFAULT false;
CREATE TABLE public.asaas_contracts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES public.profiles(id), subscription_id uuid NOT NULL UNIQUE REFERENCES public.billing_subscriptions(id), environment text NOT NULL, customer_id text, remote_subscription_id text, payment_url text, consent_at timestamptz NOT NULL DEFAULT now(), paid_until date, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.asaas_contracts TO authenticated; GRANT ALL ON public.asaas_contracts TO service_role;
ALTER TABLE public.asaas_contracts ENABLE ROW LEVEL SECURITY;
CREATE POLICY asaas_contracts_read ON public.asaas_contracts FOR SELECT TO authenticated USING(profile_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TRIGGER asaas_contract_updated BEFORE UPDATE ON public.asaas_contracts FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TABLE public.asaas_payment_events(event_id text PRIMARY KEY, contract_id uuid NOT NULL REFERENCES public.asaas_contracts(id), payment_id text NOT NULL, state text NOT NULL, due_date date NOT NULL, amount_cents integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.asaas_payment_events TO authenticated; GRANT ALL ON public.asaas_payment_events TO service_role;
ALTER TABLE public.asaas_payment_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY asaas_events_admin ON public.asaas_payment_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TRIGGER asaas_event_updated BEFORE UPDATE ON public.asaas_payment_events FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE UNIQUE INDEX asaas_remote_subscription_unique ON public.asaas_contracts(environment,remote_subscription_id) WHERE remote_subscription_id IS NOT NULL;
CREATE UNIQUE INDEX asaas_charge_unique ON public.billing_charges(provider,external_id) WHERE provider='asaas' AND external_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.get_self_service_plans() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'description',description,'amount_cents',amount_cents,'features',features) ORDER BY position,created_at),'[]'::jsonb) FROM public.billing_plans WHERE active AND self_service_enabled AND audience='assinante' AND plan_type='recorrente' AND billing_interval='monthly' AND currency='BRL' AND amount_cents>0 AND contract_template_id IS NULL $$;
REVOKE ALL ON FUNCTION public.get_self_service_plans() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.get_self_service_plans() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.reserve_asaas_contract(_profile uuid,_plan uuid,_environment text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.billing_plans%ROWTYPE; s public.billing_subscriptions%ROWTYPE; c public.asaas_contracts%ROWTYPE; BEGIN IF _environment NOT IN ('production','sandbox') THEN RAISE EXCEPTION 'Ambiente inválido'; END IF; PERFORM 1 FROM public.profiles WHERE id=_profile AND is_active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Perfil inativo'; END IF; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_profile AND role IN ('admin','facilitador','membro')) THEN RAISE EXCEPTION 'Use gestão administrativa para planos de Membros'; END IF; SELECT * INTO p FROM public.billing_plans WHERE id=_plan AND active AND self_service_enabled AND audience='assinante' AND plan_type='recorrente' AND billing_interval='monthly' AND currency='BRL' AND amount_cents>0 AND contract_template_id IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Plano não disponível para contratação'; END IF; SELECT * INTO s FROM public.billing_subscriptions WHERE profile_id=_profile AND status IN ('active','draft','past_due') ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF s.id IS NOT NULL THEN SELECT * INTO c FROM public.asaas_contracts WHERE subscription_id=s.id FOR UPDATE; IF c.id IS NULL OR s.plan_id<>_plan OR c.environment<>_environment THEN RAISE EXCEPTION 'Revise a assinatura existente com o Admin'; END IF; IF s.status='active' THEN RAISE EXCEPTION 'Assinatura já ativa'; END IF; IF c.lease_until>now() THEN RAISE EXCEPTION 'Contratação em processamento. Aguarde e tente novamente'; END IF; ELSE INSERT INTO public.billing_subscriptions(profile_id,plan_id,status,provider,start_date,next_charge_date,notes) VALUES(_profile,_plan,'draft','asaas',(now() AT TIME ZONE 'America/Sao_Paulo')::date,(now() AT TIME ZONE 'America/Sao_Paulo')::date,'Contratação self-service consentida; aguardando confirmação financeira') RETURNING * INTO s; INSERT INTO public.asaas_contracts(profile_id,subscription_id,environment) VALUES(_profile,s.id,_environment) RETURNING * INTO c; END IF; UPDATE public.asaas_contracts SET lease_until=now()+interval '2 minutes' WHERE id=c.id; RETURN to_jsonb(c)||jsonb_build_object('amount_cents',s.amount_cents,'plan_name',p.name,'start_date',s.start_date); END $$;
REVOKE ALL ON FUNCTION public.reserve_asaas_contract(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_asaas_contract(uuid,uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.apply_asaas_payment(_contract uuid,_event text,_payment text,_state text,_due date,_amount integer,_paid_at timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.asaas_contracts%ROWTYPE; s public.billing_subscriptions%ROWTYPE; expiry date; BEGIN SELECT * INTO c FROM public.asaas_contracts WHERE id=_contract; IF c.id IS NULL THEN RAISE EXCEPTION 'Contratação não encontrada'; END IF; PERFORM 1 FROM public.profiles WHERE id=c.profile_id FOR UPDATE; SELECT * INTO c FROM public.asaas_contracts WHERE id=_contract FOR UPDATE; SELECT * INTO s FROM public.billing_subscriptions WHERE id=c.subscription_id FOR UPDATE; IF _state NOT IN ('paid','pending','overdue','refunded','canceled') OR _amount<>s.amount_cents OR _due IS NULL THEN RAISE EXCEPTION 'Pagamento incompatível'; END IF; INSERT INTO public.asaas_payment_events(event_id,contract_id,payment_id,state,due_date,amount_cents) VALUES(_event,c.id,_payment,_state,_due,_amount) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN jsonb_build_object('duplicate',true); END IF; INSERT INTO public.billing_charges(subscription_id,plan_id,profile_id,amount_cents,status,due_date,paid_at,provider,external_id) VALUES(s.id,s.plan_id,c.profile_id,_amount,CASE WHEN _state='paid' THEN 'paid' WHEN _state='canceled' OR _state='refunded' THEN 'canceled' ELSE 'pending' END,_due,CASE WHEN _state='paid' THEN _paid_at END,'asaas',_payment) ON CONFLICT(provider,external_id) WHERE provider='asaas' AND external_id IS NOT NULL DO UPDATE SET status=excluded.status,paid_at=excluded.paid_at;
IF _state='paid' AND s.status NOT IN ('canceled','completed') THEN expiry:=(_due+interval '1 month')::date; UPDATE public.asaas_contracts SET paid_until=greatest(paid_until,expiry) WHERE id=c.id; IF expiry>(now() AT TIME ZONE 'America/Sao_Paulo')::date THEN IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=c.profile_id AND role IN ('admin','facilitador','membro')) THEN RAISE EXCEPTION 'Papel interno exige revisão administrativa'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=c.profile_id AND is_active) THEN RAISE EXCEPTION 'Perfil inativo exige revisão administrativa'; END IF; DELETE FROM public.user_roles WHERE user_id=c.profile_id AND role='convidado'; INSERT INTO public.user_roles(user_id,role) VALUES(c.profile_id,'assinante') ON CONFLICT DO NOTHING; UPDATE public.billing_subscriptions SET status='active',next_charge_date=greatest(next_charge_date,expiry) WHERE id=s.id; END IF; ELSIF _state IN ('overdue','refunded','canceled') AND s.status NOT IN ('canceled','completed') AND (c.paid_until IS NULL OR (_state IN ('refunded','canceled') AND (_due+interval '1 month')::date>=c.paid_until) OR c.paid_until<=(now() AT TIME ZONE 'America/Sao_Paulo')::date) THEN UPDATE public.billing_subscriptions SET status='past_due' WHERE id=s.id; END IF; RETURN jsonb_build_object('success',true); END $$;
REVOKE ALL ON FUNCTION public.apply_asaas_payment(uuid,text,text,text,date,integer,timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.apply_asaas_payment(uuid,text,text,text,date,integer,timestamptz) TO service_role;